class PiggyBank:
    def __init__(self):
        self.coins = 0

    def add(self):
        self.coins += 1

bank = PiggyBank()
bank.add()
print(bank.coins)

from dataclasses import dataclass

@dataclass
class Task:
    title: str
    done: bool = False

print(Task("Прочитать урок"))

class Engine:
    def start(self):
        return "заведён"

class Car:
    def __init__(self, engine):
        self.engine = engine

print(Car(Engine()).engine.start())

